public static int DelayMs(int baseMs, int attempt, int capMs)
{
    return Math.Min(baseMs << attempt, capMs);
}

solution:
public static int DelayMs(int baseMs, int attempt, int capMs)
{
    long delay = baseMs;
    for (int i = 0; i < attempt && delay < capMs; i++)
        delay *= 2;
    return (int)Math.Min(delay, capMs);
}

