public static int[] CopyBlocks(int[] data, int blockSize)
{
    var result = new List<int>();
    for (int offset = 0; offset < data.Length; offset += blockSize)
    {
        var buffer = new int[blockSize];
        int read = Math.Min(blockSize, data.Length - offset);
        Array.Copy(data, offset, buffer, 0, read);
        result.AddRange(buffer);
    }
    return result.ToArray();
}

solution:
public static int[] CopyBlocks(int[] data, int blockSize)
{
    var result = new List<int>(data.Length);
    for (int offset = 0; offset < data.Length; offset += blockSize)
    {
        int read = Math.Min(blockSize, data.Length - offset);
        for (int i = 0; i < read; i++) result.Add(data[offset + i]);
    }
    return result.ToArray();
}
